INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (3, "", 6, "drama_talk_surprise_in_shy", "drama_talk_surprise_loop_shy", 0.2, 129811, 1, 6014, 0, "");
INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (21, "", 6, "vo_minigame_1013_top_talk_6_002", 0, "", "vo_minigame_1013", "", 6015, 0, "");
INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (11, 0.3, 6, "いやいや何でもない！\nあたしは別に変なこと\n考えてないからな！\nそれより訓練だっ！", 1, 0, 129811, 0, 6016, 9, 0);
