INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (21, "", 7, "vo_minigame_1013_top_talk_7_002", 0, "", "vo_minigame_1013", "", 7015, 0, "");
INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (11, 0.5, 7, "彼らが私に逆らわずに\n努力したからこそ、\n得たものもありますし\n…感謝しておきますわ", 1, 0, 129911, 0, 7016, 6, 0);
