INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (21, "", 8, "vo_minigame_1013_top_talk_8_002", 0, "", "vo_minigame_1013", "", 8015, 0, "");
INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (11, 0.3, 8, "くっ、そう言われると\n悔しいな…！\nならこの行軍訓練で\n逆転してやるぜ！", 1, 0, 129811, 0, 8016, 7, 0);
